import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CGregAndFriends solver = new CGregAndFriends();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGregAndFriends {
        long mod = 1000000007;
        long INF = (long) 1e18 + 1;
        long[][] nCr = new long[100][100];

        long f(long p, int a, int b, int c, int d) {
            p *= nCr[a][b];
            p %= mod;
            p *= nCr[c][d];
            p %= mod;
            return p;
        }

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int K = in.nextInt();
            int cnt1 = 0, cnt2 = 0;
            for (int i = 0; i < 100; i++) {
                for (int j = 0; j <= i; j++) {
                    if (j == 0 || j == i) nCr[i][j] = 1;
                    else nCr[i][j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
                }
            }
            for (int i = 0; i < n; i++) {
                if (in.nextInt() == 50) cnt1++;
                else cnt2++;
            }
            long[][][] dist = new long[200][200][2];
            long[][][] dp = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                }
            }
            dist[0][0][0] = 0;
            dp[0][0][0] = 1;
            int[] qx = new int[80000];
            int[] qy = new int[80000];
            int[] qz = new int[80000];
            int head = 0, tail = 0;
            qx[tail] = 0;
            qy[tail] = 0;
            qz[tail++] = 0;
            while (head < tail) {
                int x = qx[head];
                int y = qy[head];
                int z = qz[head++];
                long d = dist[x][y][z];
                if (z == 0) {
                    int rx = cnt1 - x;
                    int ry = cnt2 - y;
                    for (int i = 0; i <= rx; i++) {
                        for (int j = 0; j <= ry; j++) {
                            if (i + j == 0) continue;
                            if (i * 50 + j * 100 > K) break;
                            int nx = x + i;
                            int ny = y + j;
                            int nz = 1;
                            if (dist[nx][ny][nz] >= d + 1) {
                                long add = f(dp[x][y][z], rx, i, ry, j);
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    qx[tail] = nx;
                                    qy[tail] = ny;
                                    qz[tail++] = nz;
                                }
                                dp[nx][ny][nz] = (dp[nx][ny][nz] + add) % mod;
                            }
                        }
                    }
                } else {
                    int rx = x;
                    int ry = y;
                    for (int i = 0; i <= rx; i++) {
                        for (int j = 0; j <= ry; j++) {
                            if (i + j == 0) continue;
                            if (i * 50 + j * 100 > K) break;
                            int nx = x - i;
                            int ny = y - j;
                            int nz = 0;
                            if (dist[nx][ny][nz] >= d + 1) {
                                long add = f(dp[x][y][z], rx, i, ry, j);
                                if (dist[nx][ny][nz] > d + 1) {
                                    dist[nx][ny][nz] = d + 1;
                                    qx[tail] = nx;
                                    qy[tail] = ny;
                                    qz[tail++] = nz;
                                }
                                dp[nx][ny][nz] = (dp[nx][ny][nz] + add) % mod;
                            }
                        }
                    }
                }
            }
            if (dist[cnt1][cnt2][1] == INF) out.println(-1);
            else out.println(dist[cnt1][cnt2][1]);
            out.println(dp[cnt1][cnt2][1]);
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new UnknownError();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
